import{b as d,O as a,g as r,j as e}from"./chunks/framework.DSt9LnBW.js";const c=JSON.parse('{"title":"2026 AI 质量元年，测试应该怎么做？","description":"提测前一天，需求又改了两处。你把变更丢给 AI，十分钟生成了四十条用例。点开一看：三十条只断言「接口返回 200」，剩下十条在重测登录，真正该补的那个异常分支——第三方回调超时——一条都没有。这不是工具不好用，而是 2026 年测试工作的缩影：写的成本没了，判断的成本还在，而且更贵了。","frontmatter":{"date":"2026-11-22T00:00:00.000Z","tags":["测试","职业发展","AI测试","质量工程"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/testing/testing-status-and-outlook-2026/index.md","filePath":"个人博客/测试/17.2026 AI 质量元年，测试应该怎么做？.md","lastUpdated":1795570552000}'),s={name:"blog/testing/testing-status-and-outlook-2026/index.md"};function l(o,t,i,h,n,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_2026-ai-质量元年-测试应该怎么做" tabindex="-1">2026 AI 质量元年，测试应该怎么做？ <a class="header-anchor" href="#_2026-ai-质量元年-测试应该怎么做" aria-label="Permalink to &quot;2026 AI 质量元年，测试应该怎么做？&quot;">​</a></h1><p>提测前一天，需求又改了两处。你把变更丢给 AI，十分钟生成了四十条用例。点开一看：三十条只断言「接口返回 200」，剩下十条在重测登录，真正该补的那个异常分支——第三方回调超时——一条都没有。</p><p>这不是工具不好用，而是 2026 年测试工作的缩影：<strong>写的成本没了，判断的成本还在，而且更贵了。</strong></p><p>每年都有人问同一个问题：测试还有没有前途？</p><p>今年的答案比往年更具体：<strong>一部分岗位确实在消失，另一部分需求在快速变大，最难的是中间那一层。</strong> 只会照着用例点页面、只会录脚本、只会报「执行率 98%」的人，正在被工具和更便宜的人替代；而能定义验收标准、能搭质量门禁、能给 AI 输出定对错的人，反而比以前更稀缺。</p><p>这篇文章不谈情怀，只谈四件事：现在变成了什么样、工具该怎么选、前景在哪、以及从明天开始能做什么。</p><h2 id="先给结论" tabindex="-1">先给结论 <a class="header-anchor" href="#先给结论" aria-label="Permalink to &quot;先给结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>判断</th><th>结论</th><th>落到个人身上</th></tr></thead><tbody><tr><td>岗位总量</td><td>收缩，且向「研发内部质量」转移</td><td>纯执行岗减少，复合岗增加</td></tr><tr><td>工作内容</td><td>执行被自动化，判断被放大</td><td>值钱的是「测什么」和「算不算过」</td></tr><tr><td>能力重心</td><td>从工具使用转向标准定义</td><td>会写脚本只是入场券</td></tr><tr><td>技术栈</td><td>接口/契约为主力，E2E 少而精，AI 评测成为新品类</td><td>别再把 UI 全量回归当主战场</td></tr><tr><td>前景</td><td>不是消失，是分层</td><td>往上走是质量工程，往下走是外包</td></tr></tbody></table><p>一句话：<strong>测试的门槛没有变低，只是换了位置——从「会不会点」换成了「能不能定义对错、能不能证明它对」。</strong></p><h2 id="一、五个真实现状" tabindex="-1">一、五个真实现状 <a class="header-anchor" href="#一、五个真实现状" aria-label="Permalink to &quot;一、五个真实现状&quot;">​</a></h2><h3 id="_1-ai-把「写」的成本打没了-瓶颈挪到了「判断」" tabindex="-1">1. AI 把「写」的成本打没了，瓶颈挪到了「判断」 <a class="header-anchor" href="#_1-ai-把「写」的成本打没了-瓶颈挪到了「判断」" aria-label="Permalink to &quot;1. AI 把「写」的成本打没了，瓶颈挪到了「判断」&quot;">​</a></h3><p>几年前，一个测试工程师的时间大致是这样分配的：写用例、写脚本、造数据、配环境、跑回归、写报告。现在前四项都能让 AI 出初稿，快的话几分钟。</p><p>但快不等于对。AI 生成测试最常见的失败模式是<strong>看起来很像测试，实际没有有效断言</strong>：把需求复述成步骤，把步骤写成脚本，然后断言「页面打开了」「接口返回 200」——这种用例数量再多，也只是把「没测」包装成了「测过了」。</p><p>还有一条连锁反应容易被忽略：AI 让写代码也变快了，代码产出增加、评审变薄，缺陷更容易流到测试环节。测试从「验证实现」部分变成了「替评审兜底」——这也解释了为什么很多团队的体感是活变多了，而不是变少了。</p><table tabindex="0"><thead><tr><th>AI 擅长的</th><th>AI 不擅长的</th></tr></thead><tbody><tr><td>把需求转成用例初稿</td><td>判断哪些场景值得测</td></tr><tr><td>补参数组合、边界值</td><td>定义什么叫「通过」</td></tr><tr><td>写页面对象、封装请求</td><td>评估业务风险优先级</td></tr><tr><td>生成 mock 数据和测试数据</td><td>对业务语义负责</td></tr><tr><td>读日志、给出失败候选原因</td><td>决定这个版本能不能发</td></tr></tbody></table><p>结论很直接：<strong>测试的瓶颈已经从「生产效率」变成了「判断质量」。</strong> 会用 AI 的人产出可能是别人的三倍，但审不出来的人在制造三倍的维护债。未来两年，团队里最值钱的能力不是「写得快」，而是「一眼看出这份用例哪里没测」。</p><h3 id="_2-被测对象从确定性变成了概率性" tabindex="-1">2. 被测对象从确定性变成了概率性 <a class="header-anchor" href="#_2-被测对象从确定性变成了概率性" aria-label="Permalink to &quot;2. 被测对象从确定性变成了概率性&quot;">​</a></h3><p>这是 2026 年和过去十年最大的结构性变化。以前被测系统基本是确定性的：同样的输入、同样的配置，结果应该一样。现在越来越多的功能里嵌了模型——知识库问答、智能客服、内容生成、Agent 自动执行任务。</p><p>传统的 <code>assert resp[&quot;code&quot;] == 0</code> 在这里直接失效：</p><table tabindex="0"><thead><tr><th>维度</th><th>传统系统</th><th>大模型应用</th></tr></thead><tbody><tr><td>输出</td><td>确定性</td><td>概率性，同问不同答</td></tr><tr><td>正确答案</td><td>唯一</td><td>只有「可接受区间」</td></tr><tr><td>断言</td><td>字段等值</td><td>内容判定 + 分级评分</td></tr><tr><td>失败归因</td><td>基本是代码缺陷</td><td>检索没召回、模型编造、评分标准太严，都可能</td></tr><tr><td>回归触发</td><td>代码变更</td><td>模型版本、提示词、知识库任一变更</td></tr></tbody></table><p>于是「评测」成了测试的新品类：评测集怎么建、评分标准怎么定、幻觉怎么测、回归基线怎么维护。这块的完整做法在 <a href="/blog/testing/llm-qa-testing/">大模型问答测试怎么做</a> 里展开过，这里只说结论：</p><blockquote><p><strong>2026 年最缺的测试能力，不是写脚本，而是给不确定的输出定一套可复现的标准。</strong></p></blockquote><p>Agent 又把难度抬高了一层：它不只是「回答得对不对」，还有「工具调得对不对、步骤合不合理、有没有越权、花了多少钱、延迟能不能接受」。评测对象从一段文本，变成了一条轨迹。</p><h3 id="_3-自动化重心下移-e2e-少而精" tabindex="-1">3. 自动化重心下移，E2E 少而精 <a class="header-anchor" href="#_3-自动化重心下移-e2e-少而精" aria-label="Permalink to &quot;3. 自动化重心下移，E2E 少而精&quot;">​</a></h3><p>UI 全量回归曾经是自动化测试的代名词，现在越来越像负债：页面一改选择器就红，环境一抖就红，跑一次半小时，红了没人看，最后大家集体忽略。</p><p>2026 年比较成熟的团队，自动化分层大致是这样：</p><table tabindex="0"><thead><tr><th>层级</th><th>该测什么</th><th>不该测什么</th><th>数量</th></tr></thead><tbody><tr><td>单元测试</td><td>纯逻辑、算法、边界、状态机</td><td>页面文案、样式</td><td>最多</td></tr><tr><td>接口 / 契约</td><td>鉴权、幂等、错误码、数据流、上下游契约</td><td>页面布局</td><td>主力</td></tr><tr><td>E2E</td><td>关键用户旅程、跨系统集成</td><td>所有分支和异常组合</td><td>少量</td></tr><tr><td>生产验证</td><td>合成监控、灰度对比、告警</td><td>替代测试环境</td><td>持续</td></tr></tbody></table><p>Playwright 这类工具让 E2E 写起来更稳，但「能写」不代表「该多写」。E2E 的价值在于验证<strong>链路真的通</strong>，不在于覆盖每一个分支。把它当回归主力，维护成本会把收益吃干净。</p><p>还有一个常被忽略的指标：<strong>flaky 率</strong>。一条时红时绿的用例，比没有这条用例更糟——它训练整个团队忽略红色。自动化的第一要求是可信，其次才是覆盖。</p><h3 id="_4-质量责任扩散-左移到需求-右移到生产" tabindex="-1">4. 质量责任扩散：左移到需求，右移到生产 <a class="header-anchor" href="#_4-质量责任扩散-左移到需求-右移到生产" aria-label="Permalink to &quot;4. 质量责任扩散：左移到需求，右移到生产&quot;">​</a></h3><p>「测试是最后一道闸」这个模型正在失效，原因很简单：等到提测才发现问题，修复成本已经最高，而发布频率又不允许你在闸口慢慢磨。</p><p>于是质量责任被拆散了：</p><ul><li><strong>左移</strong>：需求评审时就问「怎么验收」「异常怎么处理」「这个功能可测吗」；设计阶段就把接口契约定下来，测试参与评审而不是接收文档。</li><li><strong>右移</strong>：发布不等于结束。灰度、特性开关、可观测性、合成监控、混沌演练，都是新的测试手段。很多问题只有在真实流量下才会出现。</li><li><strong>内建</strong>：研发自测、单测门禁、代码扫描，把一部分质量工作前移给写代码的人。</li></ul><p>测试角色因此发生变化：从「执行的最后一环」变成「定义闸门的人」。<strong>能说清楚「什么情况下不能发」，比「这个版本测了 500 条用例」有价值得多。</strong></p><h3 id="_5-工具链平台化、门禁化" tabindex="-1">5. 工具链平台化、门禁化 <a class="header-anchor" href="#_5-工具链平台化、门禁化" aria-label="Permalink to &quot;5. 工具链平台化、门禁化&quot;">​</a></h3><p>以前选工具看功能，现在看它能不能接进流水线。</p><ul><li>提交门禁：静态扫描、单测、提交信息检查</li><li>合并门禁：接口回归、增量覆盖率、契约校验</li><li>发布门禁：冒烟、性能基线、安全扫描、评测集通过率</li><li>线上门禁：错误率、延迟、业务指标异常自动回滚</li></ul><p>质量数据也从报告里搬进了看板和告警。做得好的团队，测试平台不是「给人点按钮的网站」，而是「给流水线调用的能力」——用例、环境、数据、报告都以 API 的形式存在。</p><h3 id="现状速览" tabindex="-1">现状速览 <a class="header-anchor" href="#现状速览" aria-label="Permalink to &quot;现状速览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>2020 年前后</th><th>2026 年</th></tr></thead><tbody><tr><td>主要产出</td><td>用例、缺陷单、测试报告</td><td>质量策略、评测标准、门禁规则</td></tr><tr><td>自动化重心</td><td>UI 脚本</td><td>接口 / 契约 + 关键路径 E2E</td></tr><tr><td>回归触发</td><td>版本迭代</td><td>每次提交、配置变更、模型变更</td></tr><tr><td>判断依据</td><td>人眼看</td><td>指标 + 抽样 + 评测集</td></tr><tr><td>质量归属</td><td>测试团队</td><td>全员负责，测试定标准</td></tr><tr><td>工具形态</td><td>单机工具</td><td>平台 + CI 门禁 + 可观测性</td></tr></tbody></table><h2 id="二、工具栈-谁在涨、谁在稳、谁在退" tabindex="-1">二、工具栈：谁在涨、谁在稳、谁在退 <a class="header-anchor" href="#二、工具栈-谁在涨、谁在稳、谁在退" aria-label="Permalink to &quot;二、工具栈：谁在涨、谁在稳、谁在退&quot;">​</a></h2><p>工具不用学全，但要知道哪些值得投入时间。</p><table tabindex="0"><thead><tr><th>类别</th><th>2026 年的状态</th><th>建议</th></tr></thead><tbody><tr><td>Web E2E</td><td>Playwright 成为新项目默认选择，Selenium 以存量维护为主，Cypress 新增项目减少</td><td>Playwright 建议投入；Selenium 会用即可；新项目别再选 Cypress</td></tr><tr><td>接口测试</td><td>pytest + requests / httpx 仍是主力，Postman 更多用于调试和共享</td><td>pytest 建议投入；Postman 会用即可</td></tr><tr><td>性能测试</td><td>k6、Locust 在新项目中上升，JMeter 存量为主</td><td>k6 或 Locust 选一个投入；JMeter 能用即可</td></tr><tr><td>移动端</td><td>Appium 仍是通用方案，原生、跨端与鸿蒙生态的工具链在分化</td><td>按业务需要投入，没有真机资源别硬上</td></tr><tr><td>契约测试</td><td>Pact 一类方案在微服务团队稳定使用，但没有普及</td><td>多团队微服务时投入；单体项目可以跳过</td></tr><tr><td>可观测性</td><td>OpenTelemetry 成为事实标准，测试开始直接消费 trace 和指标</td><td>建议投入，这是定位效率的分水岭</td></tr><tr><td>AI 应用评测</td><td>Promptfoo、DeepEval、Ragas 等工具出现，标准还在形成</td><td>方法论优先，工具选一个够用</td></tr><tr><td>AI 辅助测试</td><td>Copilot、Claude Code、Cursor 一类工具进入日常</td><td>建议投入，但必须配人工评审</td></tr><tr><td>低代码 / 录制回放</td><td>演示价值大于生产价值，长期维护成本高</td><td>别再新学</td></tr></tbody></table><p><strong>工具的数量在增加，但真正拉开差距的是「用工具解决什么问题」。</strong> 会用 Playwright 的人很多，能说清楚「这条 E2E 为什么必须存在、坏了说明什么」的人很少。</p><h2 id="三、三个被夸大的-四个被低估的" tabindex="-1">三、三个被夸大的，四个被低估的 <a class="header-anchor" href="#三、三个被夸大的-四个被低估的" aria-label="Permalink to &quot;三、三个被夸大的，四个被低估的&quot;">​</a></h2><p>信息越嘈杂，越要分清哪些是噪音。</p><h3 id="被夸大的" tabindex="-1">被夸大的 <a class="header-anchor" href="#被夸大的" aria-label="Permalink to &quot;被夸大的&quot;">​</a></h3><p><strong>1. 「AI 全自动测试」</strong></p><p>生成用例容易，判定对错难。没有可靠的 oracle（判定标准），就没有真正的自动化，只有自动执行。AI 可以当副驾驶，但当不了裁判——尤其当被测对象本身也是 AI 时。</p><p><strong>2. 「覆盖率」</strong></p><p>行覆盖率说明代码被执行过，不说明风险被覆盖。一个 90% 覆盖率的模块，可能恰好漏掉了唯一会出事的那个分支。覆盖率适合看趋势和找盲区，不适合当 KPI。</p><p><strong>3. 「测试已死 / 无人测试」</strong></p><p>工具能替代动作，替代不了责任。上线出问题，没人会说「是 AI 判断错的」。只要还有人要对质量负责，就需要有人定义标准、评估风险、签字放行。</p><h3 id="被低估的" tabindex="-1">被低估的 <a class="header-anchor" href="#被低估的" aria-label="Permalink to &quot;被低估的&quot;">​</a></h3><p><strong>1. 测试设计</strong></p><p>等价类、边界值、状态迁移、场景组合、风险建模——这些看起来「老派」的方法，恰恰是 AI 最不擅长的部分。AI 能帮你把用例写出来，但不能替你决定该测哪些。</p><p><strong>2. 环境与数据治理</strong></p><p>多数团队真正的瓶颈不是不会写脚本，而是环境不稳定、数据不可控、依赖服务时好时坏。能把测试环境做成「随用随起、数据可造可清」的团队，效率会甩开同行一大截。</p><p><strong>3. 可观测性与生产验证</strong></p><p>日志、指标、链路追踪不只是运维工具，也是测试工具。会看监控的人定位问题快一个数量级；会用灰度对比的人，能把「上线后才知道」变成「上线时就知道」。</p><p><strong>4. 给 AI 定标准的能力</strong></p><p>模型输出没有唯一答案，所以「什么算好」必须由人来定义。这项能力目前极度稀缺，而且很难被外包——它需要对业务和用户的理解。</p><h2 id="四、前景-三条路-和一条死路" tabindex="-1">四、前景：三条路，和一条死路 <a class="header-anchor" href="#四、前景-三条路-和一条死路" aria-label="Permalink to &quot;四、前景：三条路，和一条死路&quot;">​</a></h2><p>我的判断是：测试不会整体消失，但会明显分层。往下是执行，往上是工程和判断。</p><table tabindex="0"><thead><tr><th>路线</th><th>做什么</th><th>核心能力</th><th>适合谁</th><th>风险</th></tr></thead><tbody><tr><td><strong>A. 质量工程 / 测试架构</strong></td><td>CI 门禁、测试平台、工具链、效能度量</td><td>工程能力、系统设计、平台思维</td><td>喜欢写代码、搭系统的人</td><td>容易做成「工具组」，离业务越来越远</td></tr><tr><td><strong>B. 业务质量负责人</strong></td><td>领域质量策略、验收标准、风险判断、跨团队推动</td><td>业务理解、风险建模、沟通推动</td><td>懂业务、善于协调的人</td><td>容易被当成「高级执行」，需要主动输出标准</td></tr><tr><td><strong>C. AI 质量方向</strong></td><td>评测体系、Agent 测试、AI 辅助测试工程</td><td>评测设计、数据分析、提示词与工具链</td><td>对 AI 有热情、愿意啃新东西的人</td><td>标准还在形成，容易踩空，需要持续学习</td></tr></tbody></table><p>三条路不互斥，而且 AI 是共同的放大器：</p><ul><li>走 A：用 AI 做平台能力——用例生成、失败归因、智能选测。</li><li>走 B：用 AI 做判断辅助——快速梳理需求、生成风险清单、对比版本差异。</li><li>走 C：AI 本身就是工作对象。</li></ul><p><strong>死路只有一条：只会执行用例、只会点工具、只会报执行率和用例数。</strong> 这条路上的竞争最激烈，议价能力最低，也最容易被自动化和外包同时挤压。</p><p>现实一点说：未来几年测试岗位的总量很难反弹，「质量工程师」的需求会持续存在，薪资分化会更大。中间层最难受——往上够不着工程能力，往下又比不过刚毕业就会用 AI 的人。</p><h2 id="五、不同处境-不同的答案" tabindex="-1">五、不同处境，不同的答案 <a class="header-anchor" href="#五、不同处境-不同的答案" aria-label="Permalink to &quot;五、不同处境，不同的答案&quot;">​</a></h2><p>前面说的都是趋势，但趋势落到具体的人身上，差别很大。同样是「2026 年的测试」，在大厂、传统企业、外包公司和小团队里，面对的是四种不同的局面。</p><table tabindex="0"><thead><tr><th>处境</th><th>现在在发生什么</th><th>该抓什么</th><th>别做什么</th></tr></thead><tbody><tr><td><strong>互联网大厂 / 中厂</strong></td><td>平台和门禁基本建好，纯功能执行岗收缩最快；HC 向质量工程、效能、AI 评测倾斜</td><td>平台能力（CI、可观测、数据工厂）+ 一个专项（性能 / 安全 / AI 评测）</td><td>重复造平台；只做业务用例执行</td></tr><tr><td><strong>传统企业（金融、政企、制造）</strong></td><td>流程与合规权重高，自动化程度参差；信创、等保、审计留痕是硬要求，外包比例高</td><td>把手工流程做成可审计的自动化证据链；数据脱敏与权限；变更管理</td><td>照搬互联网「快速迭代」的话术，推不动</td></tr><tr><td><strong>外包 / 驻场</strong></td><td>交付导向，按人头和用例数计价；AI 正在压缩低端执行，甲方开始要求「能搭能测能写报告」</td><td>可迁移的工程能力（接口自动化、CI、脚本）；攒一个能带走的作品</td><td>只堆用例数量，把时间全花在填表</td></tr><tr><td><strong>小团队 / 一人测试</strong></td><td>没有平台、没有专职运维，测试要覆盖全流程；资源少，但决策链短</td><td>一条核心链路的接口回归 + 关键路径 E2E + 生产监控；优先用开源和 SaaS</td><td>上来就自建平台、追覆盖率</td></tr></tbody></table><p>两点补充：</p><ul><li><strong>行业差异往往大于公司规模差异。</strong> 金融和政企的合规成本，可能比技术栈落后更影响你的日常；互联网小团队的节奏，也可能比大厂更接近「全栈测试」。</li><li><strong>别拿别人的地图走自己的路。</strong> 大厂的平台方案搬到十人团队，通常活不过三个月；小团队的「先跑起来」搬到金融，过不了审计。先看清自己的约束条件，再选方法。</li></ul><p>工作年限不同，重点也不同，放在最后一节说。</p><h2 id="六、需要怎么做-一份能落地的清单" tabindex="-1">六、需要怎么做：一份能落地的清单 <a class="header-anchor" href="#六、需要怎么做-一份能落地的清单" aria-label="Permalink to &quot;六、需要怎么做：一份能落地的清单&quot;">​</a></h2><h3 id="_6-1-先做能力盘点" tabindex="-1">6.1 先做能力盘点 <a class="header-anchor" href="#_6-1-先做能力盘点" aria-label="Permalink to &quot;6.1 先做能力盘点&quot;">​</a></h3><p>下面十条，能独立做到的打勾。少于五条，说明现在最该补的是基本功，而不是追新概念。</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能画出核心业务链路的请求路径（页面 → 网关 → 服务 → 库/缓存）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能设计一份带明确判定标准的接口用例</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能独立定位缺陷发生在前端、后端、数据库还是环境</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能搭一条真正跑在 CI 里的回归，而不是本地脚本</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能解释一条 flaky 用例的根因并修掉它</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能定义一次发布的准出标准，并说服团队接受</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能设计评测集和评分标准，而不只是「随便问几个问题」</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能读懂日志、指标和链路追踪</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能用 AI 生成用例，并指出它漏了什么</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 能用数据说明当前质量现状和主要风险</li></ul><h3 id="_6-2-90-天行动清单" tabindex="-1">6.2 90 天行动清单 <a class="header-anchor" href="#_6-2-90-天行动清单" aria-label="Permalink to &quot;6.2 90 天行动清单&quot;">​</a></h3><p>不用等公司立项，先在自己负责的范围内做。</p><table tabindex="0"><thead><tr><th>时间</th><th>做什么</th><th>产出</th></tr></thead><tbody><tr><td>第 1–2 周</td><td>摸现状：近半年线上缺陷、flaky 用例、回归耗时、环境问题 Top 3</td><td>一页现状分析</td></tr><tr><td>第 3–4 周</td><td>选一条核心链路，把接口自动化做进 CI</td><td>一条可信的回归流水线</td></tr><tr><td>第 2 个月</td><td>加门禁和看板：合并门禁、逃逸率、回归时长</td><td>质量看板 + 门禁规则</td></tr><tr><td>第 3 个月</td><td>把 AI 接进工作流：用例初稿、失败归因、评测集</td><td>一套可复用的 AI 工作流</td></tr><tr><td>每季度</td><td>一次全链路压测或故障演练</td><td>容量结论与改进项</td></tr></tbody></table><p>关键不是做完所有事，而是<strong>先做出一条别人愿意用的东西</strong>。一条稳定跑在 CI 里、真能挡住问题的回归，比十份测试方案更有说服力。</p><h3 id="_6-3-团队层面要补的四件事" tabindex="-1">6.3 团队层面要补的四件事 <a class="header-anchor" href="#_6-3-团队层面要补的四件事" aria-label="Permalink to &quot;6.3 团队层面要补的四件事&quot;">​</a></h3><p><strong>1. 质量门禁</strong></p><p>明确三件事：什么条件下能合并、什么条件下能发布、什么情况下必须回滚。门禁要少而硬，多了等于没有。</p><p><strong>2. 分层策略</strong></p><p>写清楚哪类问题在哪一层测。单元测逻辑，接口测契约和数据流，E2E 测关键链路，生产环境测真实流量。避免所有问题都堆到 UI 回归。</p><p><strong>3. 数据与环境</strong></p><p>推动「环境即代码」：按需拉起、用完销毁；测试数据可生成、可脱敏、可清理。这件事的投入产出比通常被严重低估。</p><p><strong>4. 指标</strong></p><p>停止用「用例数」「执行率」「自动化率」证明价值，换成能反映结果的指标：</p><table tabindex="0"><thead><tr><th>指标</th><th>定义</th><th>说明什么</th><th>期望方向</th></tr></thead><tbody><tr><td>缺陷逃逸率</td><td>上线后发现的缺陷 / 总缺陷</td><td>闸门是否有效</td><td>降</td></tr><tr><td>变更失败率</td><td>发布导致回滚或紧急修复的比例</td><td>发布质量</td><td>降</td></tr><tr><td>MTTR</td><td>平均恢复时间</td><td>发现和定位能力</td><td>降</td></tr><tr><td>回归时长</td><td>从提交到拿到回归结论的时间</td><td>反馈速度</td><td>降</td></tr><tr><td>Flaky 率</td><td>不稳定用例占比</td><td>自动化可信度</td><td>降</td></tr><tr><td>缺陷前置发现率</td><td>需求/设计/开发阶段发现缺陷占比</td><td>左移效果</td><td>升</td></tr></tbody></table><p>指标不用多，三到四个就够。关键是<strong>持续看趋势</strong>，而不是月底填表。</p><h3 id="_6-4-关于-ai-把它当同事-不当替身" tabindex="-1">6.4 关于 AI：把它当同事，不当替身 <a class="header-anchor" href="#_6-4-关于-ai-把它当同事-不当替身" aria-label="Permalink to &quot;6.4 关于 AI：把它当同事，不当替身&quot;">​</a></h3><p>三个现在就能用的场景：</p><ol><li><strong>生成初稿</strong>：需求转用例、接口文档转脚本、日志转排查思路。省下的是打字时间。</li><li><strong>失败归因</strong>：把报错、日志、最近改动一起丢给模型，让它给候选原因。它经常能给到有用的方向，但结论必须自己验证。</li><li><strong>评测裁判</strong>：在大模型评测里做初筛和分级。前提是你先校准过它，并且保留人工抽检。</li></ol><p>三条红线：</p><ul><li>没评审过的 AI 用例不进回归库。</li><li>不把 AI 当唯一的判定标准，尤其是安全和合规场景。</li><li>敏感数据、用户隐私、密钥不进 prompt。</li></ul><h2 id="七、给不同阶段的人" tabindex="-1">七、给不同阶段的人 <a class="header-anchor" href="#七、给不同阶段的人" aria-label="Permalink to &quot;七、给不同阶段的人&quot;">​</a></h2><p><strong>0–2 年：先把一条业务链路吃透。</strong> 不要急着学一堆工具。能独立定位问题、能写出有断言的用例、能说清楚系统的数据流，这三件事比会五个框架更值钱。同时把 AI 用成日常工具，但每条产出都自己审一遍。</p><p><strong>3–5 年：从「测什么」升级到「怎么保证」。</strong> 这时候该选方向了：往工程走，补 CI、平台、可观测性；往业务走，补领域知识、风险建模、跨团队推动；往 AI 质量走，补评测、数据、Agent 相关能力。选一条深挖，另外两条保持能对话。</p><p><strong>测试负责人：把资源从「执行」挪到「标准与平台」。</strong> 别再用人头数证明团队价值。把重复执行交给流水线，把人的时间投到风险判断、评测标准、环境治理和故障演练上。用逃逸率和变更失败率跟老板对话，而不是用例数。</p><p><strong>想转进来的人：先想清楚为什么。</strong> 如果是因为「测试门槛低」，那这条路已经不存在了。如果是因为喜欢拆系统、找边界、定义标准，那现在反而是好时机——行业缺的正是这种人。</p><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>2026 年的测试，不是「会不会被 AI 取代」的问题，而是「你站在被取代的那一侧，还是定义标准的那一侧」。</p><p>工具会继续变快，模型会继续变强，唯一不会自动生成的东西是：<strong>知道什么值得测、什么算通过、什么情况下必须喊停。</strong> 这三件事，就是这行剩下的、也是最难被替代的部分。</p>',107)])])}const g=d(s,[["render",l]]);export{c as __pageData,g as default};
